mapper.select:
SELECT user_id, username, name, email, phone, status, roles, role_names, department_id, location_id, employee_code, is_locked, lock_time, password_error_count, last_password_error_time, need_change_password, last_password_change_time, last_login_time, last_login_ip, avatar, deleted, create_time, update_time, created_by, updated_by FROM users
AND deleted = 0
AND username LIKE CONCAT('%', #{username}, '%')
AND name LIKE CONCAT('%', #{fullName}, '%')
AND email LIKE CONCAT('%', #{email}, '%')
AND phone LIKE CONCAT('%', #{phone}, '%')
AND role = #{role}
AND status = CAST(#{status} AS INTEGER)
AND department_id = #{department}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
ORDER BY create_time DESC
